export interface CourseSummary {
  id: string;
  schoolType: number;
  yearLabel: string;
  semester: string;
  semesterLabel: string;
  semesterSlug: string;
  curriculumYear: string;
  courseCode: string;
  courseCodeDetail1: string;
  courseCodeDetail2: string;
  languageType: string;
  courseName: string;
  courseNameSlug: string;
  programLabel: string;
  departmentLabel: string | null;
  courseCategoryLabel: string | null;
  courseCodeLabel: string;
  credits: number;
  courseType: string;
  creditCategory: string;
  hasPracticalTeacher: boolean;
  sourceIndex: number;
  hasDetail: boolean;
  hasEnglishDetail: boolean;
  detailPath: string | null;
  englishDetailPath: string | null;
  detailPaths: {
    ja: string | null;
    en: string | null;
  };
  routePath: string;
}

export interface SyllabusDetail {
  sourceIndex: number;
  courseId: string;
  language?: "ja" | "en";
  sourceUrl: string;
  importedAt: string;
  title: string;
  subtitle?: string;
  courseType: string;
  credits: string;
  term: string;
  method: string;
  teachers: string[];
  keywords: string[];
  educationalGoal: string;
  advice: string;
  books: string;
  requiredKnowledge: string;
  activityGoals: Array<{ index: string; type: string; body: string }>;
  evaluationWeights: Array<{ label: string; values: string[]; columns?: string[] }>;
  achievementLevels: { ideal: string; standard: string };
  clipProcess: string;
  lessons: Array<{
    index: string;
    content: string;
    operation: string;
    assignments: string;
    minutes: string;
  }>;
  rawText: string;
}

